// spec: .qa/e2e/specs/journey.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('«המסע שלי»', () => {
  test('JR-02 Клик по аватару или имени открывает «פרופיל אישי» #f6970bc6 @prod-safe @mobile', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. Открыть `/journey` → клик по имени «אקדא טסט».
    await page.goto('/journey');
    const header = page.getByRole('button', { name: 'מעבר לפרטים שלי' });
    await expect(header).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    await header.getByText('אקדא טסט', { exact: true }).click();
    await expect(page).toHaveURL(/\/profile$/);
    await expect(page.getByRole('heading', { level: 1, name: 'פרופיל אישי' })).toBeVisible();

    // 2. Назад на `/journey` → клик по аватару (буква).
    await page.goto('/journey');
    await expect(header).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    await header.getByText('א', { exact: true }).click();
    await expect(page).toHaveURL(/\/profile$/);
    await expect(page.getByRole('heading', { level: 1, name: 'פרופיל אישי' })).toBeVisible();
  });
});
